import {fieldNotebook} from './field-notebook-core.mjs';
import {rainPaths,rainResult,rainResultSourceValid} from './rain-paths-core.mjs';
import {rainCaseById} from './rain-paths-content.mjs';
import {RAIN_NOTEBOOK_PAGES as PAGES,RAIN_NOTEBOOK_TASKS as TASKS,RAIN_NOTEBOOK_READ as READ,RAIN_NOTEBOOK_SUPPORT as SUPPORT,RAIN_NOTEBOOK_ORIGINS as ORIGINS,RAIN_NOTEBOOK_QUANTITIES as QUANTITIES,RAIN_NOTEBOOK_DATUM_IDS as IDS,rainNotebookRows,rainNotebookQuestion} from './rain-notebook-content.mjs';
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x),clone=x=>JSON.parse(JSON.stringify(x));
const keys=(x,required,optional=[])=>object(x)&&required.every(k=>Object.hasOwn(x,k))&&Object.keys(x).every(k=>required.includes(k)||optional.includes(k));
function same(a,b){if(a===b)return true;if(Array.isArray(a)||Array.isArray(b))return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((v,i)=>same(v,b[i]));return object(a)&&object(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&same(a[k],b[k]));}
const whole=n=>Number.isInteger(n)&&n>=0&&n<=24,raw=t=>typeof t==='string'&&t.length<=16;
const supportValid=s=>object(s)&&Object.entries(s).every(([k,v])=>SUPPORT.includes(k)&&v===true);
const supportsValid=s=>object(s)&&Object.entries(s).every(([k,v])=>TASKS.includes(k)&&supportValid(v));
const sourceValid=s=>keys(s,['origin','result'])&&ORIGINS.includes(s.origin)&&rainResultSourceValid(s.result);
const viewsValid=v=>keys(v,['page','readPrompt'])&&PAGES.includes(v.page)&&READ.includes(v.readPrompt);
const choiceValid=x=>x===null||['A','B','same','unsure'].includes(x);
function fieldsValid(s){return keys(s,['selected','values','pending','quantity'])&&Array.isArray(s.selected)&&s.selected.length<=2&&new Set(s.selected).size===s.selected.length&&s.selected.every(id=>IDS.includes(id))&&object(s.values)&&Object.keys(s.values).length===s.selected.length&&s.selected.every(id=>Object.hasOwn(s.values,id)&&(s.values[id]===null||whole(s.values[id])))&&keys(s.pending,['bars','modelChoice','difference'])&&object(s.pending.bars)&&Object.keys(s.pending.bars).length===s.selected.length&&s.selected.every(id=>Object.hasOwn(s.pending.bars,id)&&raw(s.pending.bars[id]))&&choiceValid(s.pending.modelChoice)&&raw(s.pending.difference)&&(s.quantity===null||QUANTITIES.some(q=>q.id===s.quantity));}
const fields=s=>({selected:s.selected,values:s.values,pending:s.pending,quantity:s.quantity});
function snapshotValid(s,id){return keys(s,['caseId','source','question','selected','values','pending','quantity','support','familiar'])&&s.caseId===id&&sourceValid(s.source)&&s.source.result.caseId===id&&same(s.question,rainNotebookQuestion(s.source))&&fieldsValid(fields(s))&&supportsValid(s.support)&&s.familiar===true;}
export function rainNotebookDataResult(s){
 const rows=rainNotebookRows(s.source).filter(r=>s.selected.includes(r.id)),issues=[];
 if(rows.length<2)issues.push('missing');
 if(rows.length===2&&rows[0].quantity!==rows[1].quantity)issues.push('mixed-quantities');
 if(rows.length===2&&rows[0].trayId===rows[1].trayId)issues.push('same-tray');
 if(rows.some(r=>r.quantity!=='runoffNew'))issues.push('wrong-quantity');
 const matches=rows.length===2&&issues.length===0;
 const feedback=matches?'These are the requested new-runoff rows: one from each tray of this frozen completed machine result.':issues.map(issue=>({missing:'Choose two rows; a missing row is not a zero.', 'mixed-quantities':'These rows count different destinations of new rain. The question compares new runoff.', 'same-tray':'Both rows describe the same tray. The question compares tray A with tray B.', 'wrong-quantity':'Newly stored tokens are useful data, but this question asks about new runoff.'}[issue])).join(' ');
 return {matches,issues,status:matches?'requested-pair':issues[0],feedback};
}
export function rainNotebookChartResult(s){
 const data=rainNotebookDataResult(s),all=rainNotebookRows(s.source),rows=s.selected.map(id=>all.find(r=>r.id===id));
 const quantity={matches:rows.length>0&&rows.every(r=>r.quantity===s.quantity),feedback:rows.length===0?'Choose source rows before comparing a quantity label.':s.quantity===null?'Choose a quantity label for your chart.':rows.every(r=>r.quantity===s.quantity)?'The quantity label agrees with each selected source row.':'The chosen quantity label differs from at least one selected source row.'};
 const bars=rows.map(r=>{const entered=s.values[r.id],matches=entered===null?null:entered===r.value;return {id:r.id,entered,expected:r.value,matches,feedback:entered===null?`${r.label}: no value is applied yet; the source is ${r.value} model-water tokens.`:`${r.label}: your draft says ${entered}; the source says ${r.value} model-water tokens.${matches?' These values agree.':' These values differ.'}`};});
 return {data,quantity,bars,complete:bars.length===2&&bars.every(b=>b.entered!==null),faithful:bars.length===2&&quantity.matches&&bars.every(b=>b.matches===true)};
}
export function rainNotebookDraftReading(s){if(s.selected.length!==2)return null;const [a,b]=s.selected.map(id=>s.values[id]);return a===null||b===null?null:a===b?'same':a>b?'first':'second';}
function resultFor(task,s,response){
 if(task==='data')return response===null?rainNotebookDataResult(s):null;
 if(task==='chart')return response===null?rainNotebookChartResult(s):null;
 if(task==='draft'){if(!['first','second','same'].includes(response))return null;const answer=rainNotebookDraftReading(s);if(answer===null)return null;const [a,b]=s.selected.map(id=>s.values[id]);return {correct:response===answer,answer,feedback:`Reading your entered draft: the first bar is ${a}, the second is ${b} model-water tokens. ${answer==='same'?'They are equal.':`The ${answer} bar is longer.`} This does not say whether those entries match the source or answer the question.`};}
 if(task==='source'){if(!['yes','differs','unsure'].includes(response))return null;const chart=rainNotebookChartResult(s),answer=chart.faithful?'yes':'differs';return {correct:response===answer,answer,faithful:chart.faithful,relevant:chart.data.matches,feedback:`${chart.faithful?'The entered values and quantity agree with their selected source rows.':'Some entered values or the quantity label are blank or differ from their selected source rows.'} ${chart.data.matches?'These rows also answer the requested runoff question.':'Whether those rows answer the runoff question is separate: this selection does not match the requested pair.'}`};}
 if(task==='model'){if(!keys(response,['choice','difference'])||!['A','B','same','unsure'].includes(response.choice)||!(response.difference===null||whole(response.difference)))return null;const q=rainNotebookQuestion(s.source),rows=rainNotebookRows(s.source),a=rows.find(r=>r.id==='A:runoffNew').value,b=rows.find(r=>r.id==='B:runoffNew').value;return {comparisonCorrect:response.choice===q.answer,differenceCorrect:response.difference===null?null:response.difference===q.difference,answer:q.answer,difference:q.difference,feedback:`The requested frozen source says tray A: ${a}, tray B: ${b} new-runoff tokens. ${q.answer==='same'?'The amounts are equal.':`Tray ${q.answer} has more new runoff.`} The absolute difference is ${q.difference} model-water tokens. These counts do not establish a real-world cause or safety verdict.`};}
 return null;
}
function checkValid(a,id){return keys(a,['task','snapshot','response','result','support','practice','familiar'])&&['data','chart',...READ].includes(a.task)&&snapshotValid(a.snapshot,id)&&supportValid(a.support)&&same(a.support,a.snapshot.support[a.task]??{})&&a.practice===true&&a.familiar===true&&resultFor(a.task,a.snapshot,a.response)!==null&&same(a.result,resultFor(a.task,a.snapshot,a.response));}
function keptValid(k,id){return k===null||keys(k,['draft','checks','revised'])&&snapshotValid(k.draft,id)&&object(k.checks)&&Object.entries(k.checks).every(([task,a])=>['data','chart',...READ].includes(task)&&a?.task===task&&checkValid(a,id))&&typeof k.revised==='boolean';}
function workValid(w,id){return keys(w,['source','selected','values','pending','quantity','support','familiar','views','checks','kept'])&&sourceValid(w.source)&&w.source.result.caseId===id&&fieldsValid(fields(w))&&supportsValid(w.support)&&w.familiar===true&&viewsValid(w.views)&&Array.isArray(w.checks)&&w.checks.length<=24&&w.checks.every(a=>checkValid(a,id))&&keptValid(w.kept,id);}
function valid(r){return keys(r,['version','currentCase','resultsExposed','exposureUnknown','cases'],['recovered'])&&r.version===1&&(r.currentCase===null||rainCaseById(r.currentCase))&&typeof r.resultsExposed==='boolean'&&typeof r.exposureUnknown==='boolean'&&object(r.cases)&&Object.keys(r.cases).length<=4&&Object.entries(r.cases).every(([id,w])=>rainCaseById(id)&&workValid(w,id))&&(r.currentCase===null?Object.keys(r.cases).length===0:Object.hasOwn(r.cases,r.currentCase));}
const fresh=()=>({version:1,currentCase:null,resultsExposed:false,exposureUnknown:false,cases:{}});
const freshWork=source=>({source:clone(source),selected:[],values:{},pending:{bars:{},modelChoice:null,difference:''},quantity:null,support:{},familiar:true,views:{page:'data',readPrompt:'draft'},checks:[],kept:null});
// The cress selector owns the outer root; this selector alone interprets its rain branch.
export function rainNotebook(state){if(!fieldNotebook(state))return null;const r=state.fieldNotebook?.rain;return r===undefined?fresh():valid(r)?r:null;}
function change(state,fn){const current=rainNotebook(state);if(!current)return false;const next=clone(current),result=fn(next);if(result===false||!valid(next))return false;const outer=clone(state.fieldNotebook??fieldNotebook({}));outer.rain=next;state.fieldNotebook=outer;return result??true;}
export function recoverRainNotebook(state){if(!fieldNotebook(state)||state.fieldNotebook?.rain===undefined||rainNotebook(state))return false;const outer=clone(state.fieldNotebook);outer.rain={...fresh(),exposureUnknown:true,recovered:outer.rain};state.fieldNotebook=outer;return true;}
export function rainNotebookInvitation(state,caseId,origin){if(!rainCaseById(caseId)||!ORIGINS.includes(origin))return null;const r=rainPaths(state);if(!r)return null;const result=origin==='current-completed'?rainResult(state,caseId):r.cases[caseId]?.keptResult??null;return rainResultSourceValid(result)?clone({origin,result}):null;}
export function inviteRainNotebook(state,shown,{replace=false}={}){
 if(!sourceValid(shown)||typeof replace!=='boolean')return false;const eligible=rainNotebookInvitation(state,shown.result.caseId,shown.origin);if(!eligible||!same(eligible,shown))return false;
 return change(state,r=>{const id=shown.result.caseId,old=r.cases[id];if(!old||replace){const w=freshWork(shown);if(old){w.checks=clone(old.checks);w.kept=clone(old.kept);w.support=clone(old.support);}r.cases[id]=w;}r.currentCase=id;return {caseId:id,reused:!!old&&!replace,replaced:!!old&&replace};});
}
const current=r=>r.currentCase===null?null:r.cases[r.currentCase];
export function chooseRainNotebookCase(state,id){if(!rainCaseById(id))return false;return change(state,r=>{if(!Object.hasOwn(r.cases,id))return false;r.currentCase=id;});}
export function setRainNotebookPage(state,page){if(!PAGES.includes(page))return false;return change(state,r=>{const w=current(r);if(!w)return false;w.views.page=page;});}
export function setRainNotebookReadPrompt(state,prompt){if(!READ.includes(prompt))return false;return change(state,r=>{const w=current(r);if(!w)return false;w.views.readPrompt=prompt;});}
export function toggleRainNotebookRow(state,id){if(!IDS.includes(id))return false;return change(state,r=>{const w=current(r);if(!w)return false;const i=w.selected.indexOf(id);if(i>=0){w.selected.splice(i,1);delete w.values[id];delete w.pending.bars[id];return {selected:false};}if(w.selected.length>=2)return false;w.selected.push(id);w.values[id]=null;w.pending.bars[id]='';return {selected:true};});}
export function setRainNotebookQuantity(state,id){if(id!==null&&!QUANTITIES.some(q=>q.id===id))return false;return change(state,r=>{const w=current(r);if(!w)return false;w.quantity=id;});}
export function setRainNotebookBarInput(state,id,text){if(!raw(text))return false;return change(state,r=>{const w=current(r);if(!w||!Object.hasOwn(w.pending.bars,id))return false;w.pending.bars[id]=text;});}
export function setRainNotebookValue(state,id,value){if(value!==null&&!whole(value))return false;return change(state,r=>{const w=current(r);if(!w||!Object.hasOwn(w.values,id))return false;w.values[id]=value;w.pending.bars[id]=value===null?'':String(value);});}
const parse=text=>{const t=text.trim();return t===''?{valid:true,value:null}:/^(?:0|[1-9]\d?)$/.test(t)&&whole(Number(t))?{valid:true,value:Number(t)}:{valid:false};};
export function adjustRainNotebookBar(state,id,delta){if(![-4,-1,1,4].includes(delta))return false;return change(state,r=>{const w=current(r);if(!w||!Object.hasOwn(w.values,id))return false;const p=parse(w.pending.bars[id]);if(!p.valid)return {valid:false,error:'Edit this entry to a whole number from 0 to 24, or Clear it. Your text is still here.'};const n=Math.max(0,Math.min(24,(p.value??0)+delta));w.values[id]=n;w.pending.bars[id]=String(n);return {valid:true,value:n};});}
export function setRainNotebookModelInput(state,field,value){if(field==='choice'&&choiceValid(value))return change(state,r=>{const w=current(r);if(!w)return false;w.pending.modelChoice=value;});if(field==='difference'&&raw(value))return change(state,r=>{const w=current(r);if(!w)return false;w.pending.difference=value;});return false;}
export function useRainNotebookSupport(state,task,kind){if(!TASKS.includes(task)||!SUPPORT.includes(kind))return false;return change(state,r=>{const w=current(r);if(!w)return false;w.support[task]??={};w.support[task][kind]=true;});}
function snapshot(r){const w=current(r);return w?{caseId:r.currentCase,source:clone(w.source),question:rainNotebookQuestion(w.source),...clone(fields(w)),support:clone(w.support),familiar:true}:null;}
export function rainNotebookSnapshot(state){const r=rainNotebook(state);return r?snapshot(r):null;}
function push(r,task,response){const w=current(r),draft=snapshot(r),result=resultFor(task,draft,response);if(result===null)return false;const entry={task,snapshot:draft,response:clone(response),result:clone(result),support:clone(w.support[task]??{}),practice:true,familiar:true};w.checks.push(entry);w.checks=w.checks.slice(-24);return clone(entry);}
export function checkRainNotebookData(state){return change(state,r=>current(r)?push(r,'data',null):false);}
export function checkRainNotebookChart(state){return change(state,r=>{const w=current(r);if(!w)return false;const entries=w.selected.map(id=>({id,...parse(w.pending.bars[id])})),bad=entries.filter(x=>!x.valid).map(x=>x.id);if(bad.length)return {valid:false,invalidIds:bad,error:'Use whole numbers from 0 to 24, or leave a bar blank. Your entries are still here; no check was recorded.'};for(const {id,value} of entries)w.values[id]=value;return {valid:true,check:push(r,'chart',null)};});}
export function answerRainNotebookDraft(state,choice){return change(state,r=>current(r)?push(r,'draft',choice):false);}
export function answerRainNotebookSource(state,choice){return change(state,r=>current(r)?push(r,'source',choice):false);}
export function answerRainNotebookModel(state){return change(state,r=>{const w=current(r);if(!w)return false;const difference=parse(w.pending.difference);if(w.pending.modelChoice===null||!difference.valid)return {valid:false,error:'Choose a comparison. Leave the difference blank, or enter a whole number from 0 to 24.'};return {valid:true,check:push(r,'model',{choice:w.pending.modelChoice,difference:difference.value})};});}
export function keepRainNotebookDraft(state){return change(state,r=>{const w=current(r);if(!w)return false;w.kept={draft:snapshot(r),checks:Object.fromEntries(w.checks.map(a=>[a.task,clone(a)])),revised:w.kept!==null};return clone(w.kept);});}
export function rainNotebookView(state,id){const r=rainNotebook(state);if(!r)return null;const caseId=id??r.currentCase;if(id!==undefined&&(!rainCaseById(id)||!r.cases[id]))return null;const w=caseId===null?null:r.cases[caseId];if(!w)return {caseId:null,work:null,source:null,rows:[],selectedRows:[],views:{page:'data',readPrompt:'draft'},snapshot:null,question:null,checks:{},chartResult:null};const copy=clone(w),rows=rainNotebookRows(copy.source),snap={caseId,source:clone(copy.source),question:rainNotebookQuestion(copy.source),...clone(fields(copy)),support:clone(copy.support),familiar:true};return {caseId,work:copy,source:copy.source,rows,selectedRows:copy.selected.map(id=>rows.find(r=>r.id===id)),views:copy.views,snapshot:snap,question:snap.question,checks:Object.fromEntries(copy.checks.map(a=>[a.task,a])),chartResult:rainNotebookChartResult(snap)};}
export function rainNotebookDisplayExposure(state,view='notebook'){const r=rainNotebook(state);if(!r)return {results:false,unknown:true,facts:[]};if(!['notebook','notes','source'].includes(view))return {results:false,unknown:false,facts:[]};const w=current(r);const shown=!!w&&(w.views.page==='data'||w.selected.length>0||w.views.page==='read'&&w.views.readPrompt==='model'||w.views.page==='chart'&&(w.checks.findLast(c=>c.task==='chart')?.result.bars.length??0)>0);return {results:view==='notes'?Object.keys(r.cases).length>0:view==='source'?!!w:shown,unknown:r.exposureUnknown,facts:[]};}
export function rainNotebookKnownExposure(state){const r=rainNotebook(state);return r?{results:r.resultsExposed,unknown:r.exposureUnknown,facts:[]}:{results:false,unknown:true,facts:[]};}
export function noteRainNotebookExposure(state,exposure){if(!keys(exposure,['results','unknown','facts'])||typeof exposure.results!=='boolean'||typeof exposure.unknown!=='boolean'||!Array.isArray(exposure.facts)||exposure.facts.length!==0)return false;return change(state,r=>{r.resultsExposed ||= exposure.results;r.exposureUnknown ||= exposure.unknown;});}
